import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/cyclehire_w002.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Index for each borough
data['StartBorough'] = pd.to_numeric(data['StartBorough'])
data['EndBorough'] = pd.to_numeric(data['EndBorough'])

boroughs = data['StartBorough'].unique()
self_containment_index = {}

for borough in boroughs:
    departures = len(data[data['StartBorough'] == borough])
    self_contained_trips = len(data[(data['StartBorough'] == borough) & (data['EndBorough'] == borough)])
    arrival_share = len(data[data['EndBorough'] == borough]) / len(data)
    expected_self_contained_trips = departures * arrival_share
    self_containment_index[borough] = self_contained_trips / expected_self_contained_trips

# Identify HOT SPOT and COLD SPOT boroughs
hot_spots = []
cold_spots = []

for borough in boroughs:
    # Shuffle trip data 500 times to create a null distribution of Self-Containment Index values
    null_distribution = []
    for _ in range(500):
        data_shuffled = data.sample(frac=1).reset_index(drop=True)
        null_distribution.append(data_shuffled['StartBorough'].value_counts(normalize=True)['StartBorough'].loc[borough] / data_shuffled['EndBorough'].value_counts(normalize=True)['EndBorough'])

    # Calculate the actual Self-Containment Index value
    actual_self_containment_index = self_containment_index[borough]

    # Determine if the actual Self-Containment Index value is statistically significant
    p_value = np.mean([x < actual_self_containment_index for x in null_distribution])

    # Check if the borough is a HOT SPOT or COLD SPOT
    if p_value < 0.05:
        if actual_self_containment_index > 1:
            hot_spots.append((borough, actual_self_containment_index))
        else:
            cold_spots.append((borough, actual_self_containment_index))

# Determine if a borough is surrounded by other high-Self-Containment Index neighboring boroughs or low-Self-Containment Index neighboring boroughs
for borough in boroughs:
    neighbors = adjacency[adjacency['borough'] == borough]['neighbor'].unique()
    self_containment_index_neighbors = {}
    for neighbor in neighbors:
        self_containment_index_neighbors[neighbor] = self_containment_index[neighbor]
    if borough in hot_spots:
        if all(x > 1 for x in self_containment_index_neighbors.values()):
            hot_spots.append((borough, self_containment_index[borough]))
    elif borough in cold_spots:
        if all(x < 1 for x in self_containment_index_neighbors.values()):
            cold_spots.append((borough, self_containment_index[borough]))

# Print the results
print(f"data_points_used = {len(data)}")
for borough, index in hot_spots + cold_spots:
    print(f"{borough} ({'HH' if index > 1 else 'LL'}, statistical method={index})")

# Print the final answer
if hot_spots and cold_spots:
    print("FINAL ANSWER: ", end="")
    for i, (borough, _) in enumerate(hot_spots):
        print(f"{borough} (HH, statistical method={self_containment_index[borough]})", end="")
        if i < len(hot_spots) - 1:
            print(", ", end="")
    for i, (borough, _) in enumerate(cold_spots):
        print(f"{borough} (LL, statistical method={self_containment_index[borough]})", end="")
        if i < len(cold_spots) - 1:
            print(", ", end="")
    print()
else:
    print("FINAL ANSWER: none")
